-- Empty, relational contracts for later gated modules. No invented evidence seeded.
CREATE TABLE roots(id TEXT PRIMARY KEY, ascii_root TEXT NOT NULL UNIQUE, unicode_root TEXT NOT NULL);
ALTER TABLE domains ADD COLUMN root_id TEXT REFERENCES roots(id);
CREATE TABLE companies(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),name TEXT NOT NULL,root_id TEXT REFERENCES roots(id),official_domain_id TEXT REFERENCES domains(id),website_verified INTEGER NOT NULL DEFAULT 0,matching_com_status TEXT NOT NULL DEFAULT 'unknown',employees INTEGER,funding_amount REAL,funding_currency TEXT,launch_date TEXT,independent_evidence_json TEXT NOT NULL DEFAULT '[]',observed_at TEXT NOT NULL);
CREATE INDEX companies_scope ON companies(tenant_id,root_id);
CREATE TABLE domain_statuses(id TEXT PRIMARY KEY,domain_id TEXT NOT NULL REFERENCES domains(id),observation_id TEXT REFERENCES observations(id),registration_state TEXT NOT NULL CHECK(registration_state IN ('unknown','registered','possibly_available','available_confirmed')),creation_date TEXT,expiration_date TEXT,registrar TEXT,nameservers_json TEXT,statuses_json TEXT,source_url TEXT NOT NULL,observed_at TEXT NOT NULL);
CREATE TABLE tld_observations(id TEXT PRIMARY KEY,root_id TEXT REFERENCES roots(id),domain_id TEXT REFERENCES domains(id),tenant_id TEXT NOT NULL REFERENCES tenants(id),actual_tlds_json TEXT,company_used_tlds_json TEXT,source TEXT NOT NULL,source_url TEXT NOT NULL,license_ref TEXT NOT NULL,observed_at TEXT NOT NULL);
CREATE TABLE history_evidence(id TEXT PRIMARY KEY,domain_id TEXT NOT NULL REFERENCES domains(id),tenant_id TEXT NOT NULL REFERENCES tenants(id),period_start TEXT,period_end TEXT,first_seen TEXT,legitimate_use INTEGER,abuse_category TEXT,redirect_target TEXT,observed_drops INTEGER,referring_domains INTEGER,backlink_count INTEGER,confidence REAL,evidence_url TEXT NOT NULL,source TEXT NOT NULL,license_ref TEXT NOT NULL,observed_at TEXT NOT NULL);
CREATE TABLE sales_comps(id TEXT PRIMARY KEY,domain_id TEXT REFERENCES domains(id),tenant_id TEXT NOT NULL REFERENCES tenants(id),domain_name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('sale','listing','estimate')),amount REAL CHECK(amount IS NULL OR amount>=0),currency TEXT,sold_date TEXT,report_date TEXT,venue TEXT,source TEXT NOT NULL,evidence_url TEXT NOT NULL,confirmation_class TEXT NOT NULL CHECK(confirmation_class IN ('verified','third_party_reported','estimated','unknown')),verification_notes TEXT,structure_json TEXT,license_ref TEXT NOT NULL,observed_at TEXT NOT NULL);
CREATE TABLE trademark_checks(id TEXT PRIMARY KEY,domain_id TEXT NOT NULL REFERENCES domains(id),tenant_id TEXT NOT NULL REFERENCES tenants(id),outcome TEXT NOT NULL DEFAULT 'not_checked' CHECK(outcome='not_checked'),reason TEXT NOT NULL DEFAULT 'deferred_by_owner',observed_at TEXT NOT NULL);
CREATE TABLE keywords(id TEXT PRIMARY KEY,term TEXT NOT NULL,language TEXT NOT NULL,normalized_term TEXT NOT NULL,UNIQUE(normalized_term,language));
CREATE TABLE trend_snapshots(id TEXT PRIMARY KEY,keyword_id TEXT NOT NULL REFERENCES keywords(id),tenant_id TEXT NOT NULL REFERENCES tenants(id),source TEXT NOT NULL,window_days INTEGER NOT NULL CHECK(window_days IN (7,30,90)),window_end TEXT NOT NULL,mentions INTEGER,baseline_mentions INTEGER,collection_volume INTEGER,independent_sources INTEGER,growth REAL,velocity REAL,acceleration REAL,novelty REAL,saturation REAL,source_url TEXT NOT NULL,license_ref TEXT NOT NULL,observed_at TEXT NOT NULL);
CREATE TABLE tld_snapshots(id TEXT PRIMARY KEY,tld TEXT NOT NULL,source TEXT NOT NULL,scope TEXT NOT NULL CHECK(scope IN ('provider_reported','registry','global_verified','unknown')),new_registrations INTEGER,transfers INTEGER,unique_registrants INTEGER,portfolio_distribution_json TEXT,holder_concentration REAL,geography_json TEXT,cross_extension_json TEXT,aftermarket_listings INTEGER,verified_sales INTEGER,registration_price REAL,renewal_price REAL,currency TEXT,renewal_observation REAL,source_url TEXT NOT NULL,license_ref TEXT NOT NULL,observed_at TEXT NOT NULL);
CREATE TABLE score_weight_sets(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),category TEXT NOT NULL,version INTEGER NOT NULL,config_json TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(tenant_id,category,version));
CREATE TABLE scores(id TEXT PRIMARY KEY,domain_id TEXT NOT NULL REFERENCES domains(id),tenant_id TEXT NOT NULL REFERENCES tenants(id),observation_id TEXT REFERENCES observations(id),dimension TEXT NOT NULL CHECK(dimension IN ('brandability','company_gap','geo_service','exact_match','trend','cleanliness','stability','extension_adoption','comparable_sales','commercial_intent','end_user_count','replacement_cost')),value REAL CHECK(value IS NULL OR (value>=0 AND value<=100)),confidence REAL,coverage REAL,model_version TEXT NOT NULL,weight_set_id TEXT REFERENCES score_weight_sets(id),supporting_evidence_json TEXT NOT NULL DEFAULT '[]',missing_fields_json TEXT NOT NULL DEFAULT '[]',risk_flags_json TEXT NOT NULL DEFAULT '[]',reason_codes_json TEXT NOT NULL DEFAULT '[]',next_action TEXT NOT NULL,observed_at TEXT NOT NULL);
CREATE INDEX scores_snapshot ON scores(tenant_id,domain_id,dimension,observed_at DESC);
CREATE TABLE review_decisions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,domain_id TEXT NOT NULL REFERENCES domains(id),label TEXT NOT NULL CHECK(label IN ('interesting','not_interesting','passed','overpriced','trademark_concern','purchased','sold','unsold','profitable','loss')),note TEXT,max_offer REAL,currency TEXT,auction_deadline TEXT,created_at TEXT NOT NULL);
CREATE TABLE purchases(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,domain_id TEXT NOT NULL REFERENCES domains(id),amount REAL CHECK(amount IS NULL OR amount>=0),currency TEXT,purchased_at TEXT,acquisition_method TEXT,evidence_url TEXT,created_at TEXT NOT NULL);
CREATE TABLE expenses(id TEXT PRIMARY KEY,purchase_id TEXT NOT NULL REFERENCES purchases(id),user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN ('transfer','renewal','commission','selling','other')),amount REAL CHECK(amount IS NULL OR amount>=0),currency TEXT,incurred_at TEXT,evidence_url TEXT);
CREATE TABLE outcomes(id TEXT PRIMARY KEY,purchase_id TEXT NOT NULL REFERENCES purchases(id),user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,status TEXT NOT NULL CHECK(status IN ('listed','sold','unsold','censored','unknown')),sale_amount REAL CHECK(sale_amount IS NULL OR sale_amount>=0),currency TEXT,listed_at TEXT,sold_at TEXT,outcome_at TEXT,net_profit REAL,roi REAL,time_to_sale_days INTEGER,evidence_url TEXT,confirmation_class TEXT NOT NULL DEFAULT 'unknown');
CREATE TABLE investor_opinions(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),public_identifier TEXT NOT NULL,source_url TEXT NOT NULL,opinion_date TEXT,domain_category TEXT,criteria_json TEXT,example_domains_json TEXT,sale_verification TEXT,interpretation TEXT,automatable_field TEXT,license_ref TEXT NOT NULL,observed_at TEXT NOT NULL);
